import{_ as n,a0 as o,w as p,s as g,ao as l,I as s,a1 as e,A as r,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"aria2 與 wget ：選擇你的下載管理器 | LCTT x X-CMD","titleTemplate":false,"description":"aria2 與 wget ：選擇你的下載管理器 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"aria2 與 wget ：選擇你的下載管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"aria2 與 wget ：選擇你的下載管理器 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20150629 Aria2 Vs Wget – Choose your Download Manager","title":"aria2 與 wget ：選擇你的下載管理器","tag":"201701","desc":""},"relativePath":"201701/20150629 Aria2 Vs Wget – Choose your Download Manager.md","filePath":"[post].md"}'),d={name:"201701/20150629 Aria2 Vs Wget – Choose your Download Manager.md"};function u(h,a,b,k,m,f){const t=o("Link");return p(),g("div",null,[a[14]||(a[14]=l('<h1 id="aria2-與-wget-選擇你的下載管理器" tabindex="-1">aria2 與 wget ：選擇你的下載管理器 <a class="header-anchor" href="#aria2-與-wget-選擇你的下載管理器" aria-label="Permalink to “aria2 與 wget ：選擇你的下載管理器”">​</a></h1><p>任何沒有下載管理器的 Linux 操作系統是不完整的。多年來，基於 Linux 的發行版使用 wget 作為默認下載管理器。它是一個很棒的小程序，可以在命令列下工作，如果你需要安裝東西、下載東西、運行 shell 腳本等，某種程度上都可以在 wget 中完成任務。在過去的很多年裏，我們發現 wget 缺乏一些高級的功能，而它的替代品 ** aria2** ，由於滿足了高級 Linux 用户的渴望而受到了許多用户的關注。我們將在本文中回顧 <strong>aria2</strong> 的安裝過程以及 wget 和 aria2 之間的區別，因此你可以決定哪個下載管理器最符合你的需要。</p><h3 id="安裝-aria2" tabindex="-1">安裝 aria2 <a class="header-anchor" href="#安裝-aria2" aria-label="Permalink to “安裝 aria2”">​</a></h3><p><strong>在 Ubuntu/Debian 中安裝 aria2：</strong></p><p>只要在 Ubuntu 中運行下面的命令安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install aria2</span></span></code></pre></div>',6)),s("p",null,[e(t,{href:"http://linuxpitstop.com/wp-content/uploads/2015/06/aria2.png"},{default:r(()=>[...a[0]||(a[0]=[s("img",{src:"http://linuxpitstop.com/wp-content/uploads/2015/06/aria2.png",alt:"aria2"},null,-1)])]),_:1})]),a[15]||(a[15]=l('<p><strong>在 Fedora/RHEL/Centos 中安裝 aria2：</strong></p><p>運行下面的命令在 Fedora/RHEL 和基於 Centos 的系統中安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install aria2</span></span></code></pre></div><p><strong>在 Arch Linux 中安裝 aria2：</strong></p><p>運行下面的命令在基於 Arch Linux 的系統中安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Sy aria2</span></span></code></pre></div><h3 id="aria2-的重要功能" tabindex="-1">aria2 的重要功能 <a class="header-anchor" href="#aria2-的重要功能" aria-label="Permalink to “aria2 的重要功能”">​</a></h3><p>讓我們來討論 aria2 中使它如此受歡迎的重要功能：</p><ul><li>通過使用多個連接下載文件，最大限度地利用可用帶寬。</li><li>同時下載多個文件和同時下載的能力。</li><li>torrent 客户端提供的所有功能都可以在這個小程序中找到。</li><li>它提供 meta 鏈接下載。</li><li>支持使用 JSON-RPC 和 XML-RPC 協議的遠程過程調用。</li><li>無需等待當前下載完成，輕鬆批量下載文件。</li></ul><h3 id="aria2-的一些副作用" tabindex="-1">aria2 的一些副作用: <a class="header-anchor" href="#aria2-的一些副作用" aria-label="Permalink to “aria2 的一些副作用:”">​</a></h3><p>aria2 的多線程機制可能會使目標服務器過載。相比下來 wget 就輕量級多了，wget 比 aria2 消耗資源少 20％。aria2 尚未經受 wget 那樣巨大的使用規模的測試，因此可能完全準備好成為默認下載管理器。</p><h3 id="wget-的重要特性" tabindex="-1">wget 的重要特性 <a class="header-anchor" href="#wget-的重要特性" aria-label="Permalink to “wget 的重要特性”">​</a></h3><ul><li>當然它是最廣泛使用和測試的下載管理器。</li><li>它是一個簡單的程序，具有較少的功能，但穩定工作了幾十年。</li><li>默認所有 Linux 發行版上都有，不需要繁重的安裝。</li><li>與 aria2 相比更輕量級。</li></ul><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>雖然 wget 沒有豐富的功能，但仍然工作得相當不錯，然而，高級用户肯定會喜歡 aria2，因為它滿足更快和併發下載的需要。aria2 可能需要很長時間來取代 wget 成為默認下載管理器，而目前 wget 用在幾乎所有 linux 發行版的安裝程序腳本中。</p><hr>',16)),s("p",null,[a[2]||(a[2]=i("via: ",-1)),e(t,{href:"http://linuxpitstop.com/aria-2-vs-wget/"},{default:r(()=>[...a[1]||(a[1]=[i("http://linuxpitstop.com/aria-2-vs-wget/",-1)])]),_:1})]),s("p",null,[a[6]||(a[6]=i("作者：",-1)),e(t,{href:"http://linuxpitstop.com/author/aun/"},{default:r(()=>[...a[3]||(a[3]=[i("Aun",-1)])]),_:1}),a[7]||(a[7]=i(" 譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:r(()=>[...a[4]||(a[4]=[i("geekpi",-1)])]),_:1}),a[8]||(a[8]=i(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:r(()=>[...a[5]||(a[5]=[i("wxy",-1)])]),_:1})]),s("p",null,[a[11]||(a[11]=i("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...a[9]||(a[9]=[i("LCTT",-1)])]),_:1}),a[12]||(a[12]=i(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:r(()=>[...a[10]||(a[10]=[i("Linux中國",-1)])]),_:1}),a[13]||(a[13]=i(" 榮譽推出",-1))])])}const T=n(d,[["render",u]]);export{C as __pageData,T as default};
